            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                while (ptr < len && buffer[ptr] <= ' ') ptr++;
            }
            int value = 0;
            while (ptr < len && buffer[ptr] > ' ') {
                value = value * 10 + buffer[ptr++] - '0';
            }
            return value;
        }
    }

    static class Tree {
        int n;
        int[] head, to, next;
        int edgeCount;

        Tree(int n) {
            this.n = n;
            head = new int[n];
            Arrays.fill(head, -1);
            to = new int[2 * (n - 1)];
            next = new int[2 * (n - 1)];
        }

        void addEdge(int a, int b) {
            to[edgeCount] = b;
            next[edgeCount] = head[a];
            head[a] = edgeCount++;
            to[edgeCount] = a;
            next[edgeCount] = head[b];
            head[b] = edgeCount++;
        }

        int[] bfs(int start, int[] parent) {
            int[] dist = new int[n];
            Arrays.fill(dist, -1);
            int[] queue = new int[n];
            int left = 0, right = 0;
            queue[right++] = start;
            dist[start] = 0;
            if (parent != null) parent[start] = -1;

            int farthest = start;
            while (left < right) {
                int u = queue[left++];
                if (dist[u] > dist[farthest]) farthest = u;
                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        if (parent != null) parent[v] = u;
                        queue[right++] = v;
                    }
                }
            }
            return new int[]{farthest, dist[farthest]};
        }

        int center() {
            int endpoint = bfs(0, null)[0];
            int[] parent = new int[n];
            int[] result = bfs(endpoint, parent);
            int otherEndpoint = result[0];
            int diameter = result[1];

            int node = otherEndpoint;
            for (int i = 0; i < diameter / 2; i++) {
                node = parent[node];
            }
            return node + 1;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        Tree circle = new Tree(n);
        for (int i = 0; i < n - 1; i++) {
